/* @lc app=leetcode id=2146 lang=kotlin */ class Solution { fun mk(s: Array<BooleanArray>, p: IntArray) = true.also { s[p[0]][p[1]] = true } fun highestRankedKItems(grid: Array<IntArray>, pricing: IntArray, start: IntArray, k: Int): List<List<Int>> = Array(grid.size) { BooleanArray(grid[0].size) }.also { mk(it, start) }.let { seen -> generateSequence(listOf(start)) { f -> f.flatMap { p -> listOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1)).map { intArrayOf(p[0] + it[0], p[1] + it[1]) } }.filter { it[0] in grid.indices && it[1] in grid[0].indices && grid[it[0]][it[1]] != 0 && !seen[it[0]][it[1]] }.distinctBy { it[0] * grid[0].size + it[1] }.onEach { mk(seen, it) }.takeIf { it.isNotEmpty() } }.map { l -> l.filter { grid[it[0]][it[1]] in pricing[0]..pricing[1] }.sortedWith(compareBy({ grid[it[0]][it[1]] }, { it[0] }, { it[1] })) }.flatten().take(k).map { listOf(it[0], it[1]) }.toList() } }